from pathlib import Path
p=Path('backend/db.js')
s=p.read_text(encoding='utf-8')
s=s.replace("_meta: { nextProductId: 1, nextCustomerId: 1, nextSupplierId: 1, nextTransactionId: 1, nextLedgerId: 1, nextDeliveryNoteId: 1 }", "_meta: { nextProductId: 1, nextCustomerId: 1, nextSupplierId: 1, nextTransactionId: 1, nextLedgerId: 1, nextDeliveryNoteId: 1, nextOrderEventId: 1 }")
s=s.replace("    if (!d._meta.nextSupplierId) d._meta.nextSupplierId = (d.suppliers||[]).length+1;", "    if (!d._meta.nextSupplierId) d._meta.nextSupplierId = (d.suppliers||[]).length+1;\n    if (!d._meta.nextOrderEventId) d._meta.nextOrderEventId = (d.order_events||[]).length+1;")
s=s.replace("for (const [collection, counter] of [['products','nextProductId'],['customers','nextCustomerId'],['suppliers','nextSupplierId'],['transactions','nextTransactionId'],['ledger','nextLedgerId']]) {\n      d._meta[counter]", "for (const [collection, counter] of [['products','nextProductId'],['customers','nextCustomerId'],['suppliers','nextSupplierId'],['transactions','nextTransactionId'],['ledger','nextLedgerId'],['order_events','nextOrderEventId']]) {\n      if (!Array.isArray(d[collection])) d[collection] = [];\n      d._meta[counter]")
s=s.replace("  if (d.order_no !== undefined && !String(d.order_no).trim()) throw new Error('订单号不能为空');", "  if (d.order_no !== undefined && !String(d.order_no).trim()) throw new Error('订单号不能为空');\n  if (['已完成', '已取消'].includes(before) && (d.quantity !== undefined || d.unit_price !== undefined)) throw new Error('终态订单不能修改数量或单价，请新建订单修正');")
s=s.replace("cache.order_events.push({id:Date.now(),order_id:x.id", "cache.order_events.push({id:cache._meta.nextOrderEventId++,order_id:x.id")
s=s.replace("for (const [collection, counter] of [['products','nextProductId'],['customers','nextCustomerId'],['suppliers','nextSupplierId'],['transactions','nextTransactionId'],['ledger','nextLedgerId'],['delivery_notes','nextDeliveryNoteId']]) next._meta[counter] = next[collection].reduce((n, row) => Math.max(n, Number(row.id) + 1), Number(next._meta[counter]) || 1);", "for (const [collection, counter] of [['products','nextProductId'],['customers','nextCustomerId'],['suppliers','nextSupplierId'],['transactions','nextTransactionId'],['ledger','nextLedgerId'],['delivery_notes','nextDeliveryNoteId'],['order_events','nextOrderEventId'],['stocktakes','nextStocktakeId']]) { next[collection] = Array.isArray(next[collection]) ? next[collection] : []; next._meta[counter] = next[collection].reduce((n, row) => Math.max(n, Number(row.id) + 1), Number(next._meta[counter]) || 1); }")
p.write_text(s,encoding='utf-8')
print('patched db')
